def column_totals(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    lines = [line.strip() for line in text.splitlines()]
    non_empty = [line for line in lines if line]
    if not non_empty:
        return {}
    header_line = non_empty[0]
    headers = [h.strip() for h in header_line.split(',')]
    num_columns = len(headers)
    data_lines = non_empty[1:]
    sums = {name: 0 for name in headers}
    for line in data_lines:
        parts = [p.strip() for p in line.split(',')]
        if len(parts) != num_columns:
            raise ValueError("Row has incorrect number of columns.")
        for i in range(num_columns):
            sums[headers[i]] += int(parts[i])
    return sums

def format_duration(seconds, style="short"):
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError("seconds must be an int")
    if style not in ("short", "long"):
        raise ValueError("style must be 'short' or 'long'")

    is_negative = seconds < 0
    abs_seconds = abs(seconds)

    if abs_seconds == 0:
        return "0s" if style == "short" else "0 seconds"

    days = abs_seconds // 86400
    remainder = abs_seconds % 86400
    hours = remainder // 3600
    remainder %= 3600
    minutes = remainder // 60
    seconds_remaining = remainder % 60

    components = []
    if days > 0:
        components.append((days, "day", "d"))
    if hours > 0:
        components.append((hours, "hour", "h"))
    if minutes > 0:
        components.append((minutes, "minute", "m"))
    if seconds_remaining > 0:
        components.append((seconds_remaining, "second", "s"))

    if not components:
        return "0s" if style == "short" else "0 seconds"

    if style == "short":
        parts = [f"{count}{abbr}" for count, _, abbr in components]
        result = " ".join(parts)
        return f"-{result}" if is_negative else result
    else:  # long style
        parts = []
        for count, unit, _ in components:
            if count == 1:
                unit_str = unit
            else:
                unit_str = unit + "s"
            parts.append(f"{count} {unit_str}")

        if len(parts) == 1:
            result = parts[0]
        else:
            all_but_last = parts[:-1]
            last = parts[-1]
            if len(all_but_last) == 1:
                result = f"{all_but_last[0]} and {last}"
            else:
                result = ", ".join(all_but_last) + f" and {last}"

        return f"minus {result}" if is_negative else result

