from collections import deque

def island_stats(grid):
    # Validate input
    if not isinstance(grid, (list, tuple)):
        raise ValueError
    if not all(isinstance(row, str) for row in grid):
        raise ValueError
    if len(grid) > 0:
        row_length = len(grid[0])
        if not all(len(row) == row_length for row in grid):
            raise ValueError
        for row in grid:
            for c in row:
                if c not in ('#', '.'):
                    raise ValueError

    rows = len(grid)
    if rows == 0:
        return (0, 0)
    cols = len(grid[0])
    if cols == 0:
        return (0, 0)

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    count = 0
    max_size = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '#' and not visited[i][j]:
                queue = deque()
                queue.append((i, j))
                visited[i][j] = True
                current_size = 1

                while queue:
                    x, y = queue.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == '#' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                queue.append((nx, ny))
                                current_size += 1

                count += 1
                if current_size > max_size:
                    max_size = current_size

    return (count, max_size)

import heapq

def course_order(n, prereqs):
    if type(n) is not int or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(prereqs, (list, tuple)):
        raise ValueError("prereqs must be a list or tuple")

    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for p in prereqs:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError("each prerequisite must be a list or tuple of two integers")
        a, b = p
        if type(a) is not int or type(b) is not int:
            raise ValueError("prerequisite elements must be integers")
        if not (0 <= a < n and 0 <= b < n):
            raise ValueError("prerequisite elements must be in range [0, n-1]")
        graph[a].append(b)
        in_degree[b] += 1

    heap = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(heap, i)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != n:
        return None
    return result

import math
from typing import Union, List, Tuple

def shoelace(points: Union[List, Tuple]) -> Tuple[int, int, str]:
    if not isinstance(points, (list, tuple)) or len(points) < 3:
        raise ValueError
    for p in points:
        if not (isinstance(p, (list, tuple)) and len(p) == 2):
            raise ValueError
        x, y = p
        if type(x) is not int or type(y) is not int:
            raise ValueError

    n = len(points)
    S = 0
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % n]
        S += x1 * y2 - x2 * y1

    twice_area = abs(S)
    if S > 0:
        orientation = "ccw"
    elif S < 0:
        orientation = "cw"
    else:
        orientation = "flat"

    boundary = 0
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % n]
        dx = x2 - x1
        dy = y2 - y1
        if dx == 0 and dy == 0:
            contrib = 0
        else:
            contrib = math.gcd(abs(dx), abs(dy))
        boundary += contrib

    return (twice_area, boundary, orientation)

