                tokens.append(word[i:i+width])
        else:
            tokens.append(word)

    lines = []
    current_line = []
    current_length = 0

    for token in tokens:
        if not current_line:
            new_length = len(token)
        else:
            new_length = current_length + 1 + len(token)

        if new_length <= width:
            current_line.append(token)
            current_length = new_length
        else:
            lines.append(current_line)
            current_line = [token]
            current_length = len(token)

    if current_line:
        lines.append(current_line)

    justified_lines = []
    num_lines = len(lines)
    for i, line in enumerate(lines):
        if i == num_lines - 1 or len(line) == 1:
            justified = ' '.join(line)
            justified += ' ' * (width - len(justified))
        else:
            total_chars = sum(len(t) for t in line)
            total_spaces = width - total_chars
            num_gaps = len(line) - 1
            if num_gaps == 0:
                justified = line[0].ljust(width)
            else:
                base, remainder = divmod(total_spaces, num_gaps)
                gaps = [base + 1 if j < remainder else base for j in range(num_gaps)]
                justified = line[0]
