def lis_stats(seq):
    if not isinstance(seq, (list, tuple)):
        raise ValueError
    for x in seq:
        if not (isinstance(x, int) and not isinstance(x, bool)):
            raise ValueError
    if len(seq) == 0:
        return (0, 1)
    n = len(seq)
    dp = [(1, 1) for _ in range(n)]
    for i in range(n):
        current_max_len = 1
        current_count = 1
        for j in range(i):
            if seq[j] < seq[i]:
                candidate_len = dp[j][0] + 1
                if candidate_len > current_max_len:
                    current_max_len = candidate_len
                    current_count = dp[j][1]
                elif candidate_len == current_max_len:
                    current_count += dp[j][1]
        dp[i] = (current_max_len, current_count)
    max_len = 0
    total_count = 0
    for i in range(n):
        if dp[i][0] > max_len:
            max_len = dp[i][0]
            total_count = dp[i][1]
        elif dp[i][0] == max_len:
            total_count += dp[i][1]
    return (max_len, total_count)

def run_stack(program):
    if not isinstance(program, (list, tuple)):
        raise ValueError("Program must be a list or tuple of strings.")
    for instr in program:
        if not isinstance(instr, str):
            raise ValueError("All instructions must be strings.")

    stack = []
    output = []
    pc = 0
    n = len(program)

    while 0 <= pc < n:
        instr = program[pc]
        parts = instr.split()
        op = parts[0]

        if op == 'push':
            stack.append(int(parts[1]))
            pc += 1

        elif op == 'pop':
            if len(stack) < 1:
                raise ValueError("Not enough elements to pop.")
            stack.pop()
            pc += 1

        elif op == 'dup':
            if len(stack) < 1:
                raise ValueError("Not enough elements to duplicate.")
            stack.append(stack[-1])
            pc += 1

        elif op == 'swap':
            if len(stack) < 2:
                raise ValueError("Not enough elements to swap.")
            a, b = stack.pop(), stack.pop()
            stack.append(a)
            stack.append(b)
            pc += 1

        elif op in ['add', 'sub', 'mul']:
            if len(stack) < 2:
                raise ValueError(f"Not enough elements for {op}.")
            b, a = stack.pop(), stack.pop()
            if op == 'add':
                stack.append(a + b)
            elif op == 'sub':
                stack.append(a - b)
            elif op == 'mul':
                stack.append(a * b)
            pc += 1

        elif op == 'print':
            if len(stack) < 1:
                raise ValueError("Not enough elements to print.")
            output.append(stack.pop())
            pc += 1

        elif op == 'jz':
            target = int(parts[1])
            if len(stack) < 1:
                raise ValueError("Not enough elements for jz.")
            val = stack.pop()
            if val == 0:
                pc = target
            else:
                pc += 1

        elif op == 'jmp':
            target = int(parts[1])
            pc = target

        elif op == 'halt':
            break

        else:
            pc += 1

    return output

