def format_duration(seconds, style="short"):
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError("Invalid type for seconds")
    if style not in ("short", "long"):
        raise ValueError("Invalid style")

    is_negative = seconds < 0
    total = abs(seconds)
    unit_info = [
        (86400, 'd', 'day'),
        (3600, 'h', 'hour'),
        (60, 'm', 'minute'),
        (1, 's', 'second'),
    ]
    parts = []
    for divisor, abbrev, name in unit_info:
        count = total // divisor
        if count > 0:
            parts.append((count, abbrev, name))
        total %= divisor

    if not parts and total == 0:
        if style == "short":
            return "0s"
        else:
            return "0 seconds"

    if style == "short":
        formatted = ' '.join([f"{count}{abbrev}" for count, abbrev, _ in parts])
        if is_negative:
            formatted = f"-{formatted}"
        return formatted
    else:
        part_strings = []
        for count, _, name in parts:
            if count == 1:
                part_str = f"{count} {name}"
            else:
                part_str = f"{count} {name}s"
            part_strings.append(part_str)

        if len(part_strings) == 0:
            return "0 seconds"
        elif len(part_strings) == 1:
            result = part_strings[0]
        else:
            if len(part_strings) == 2:
                result = f"{part_strings[0]} and {part_strings[1]}"
            else:
                all_but_last = ", ".join(part_strings[:-1])
                last = part_strings[-1]
                result = f"{all_but_last} and {last}"

        if is_negative:
            result = f"minus {result}"
        return result

