def widest_prime_gap(lo, hi):
    if not (type(lo) is int and type(hi) is int):
        raise ValueError
    if lo < 0 or hi < lo or hi > 2_000_000:
        raise ValueError

    def sieve(n):
        if n < 2:
            return []
        sieve = [True] * (n + 1)
        sieve[0], sieve[1] = False, False
        for i in range(2, int(n ** 0.5) + 1):
            if sieve[i]:
                sieve[i*i : n+1 : i] = [False] * len(sieve[i*i : n+1 : i])
        return sieve

    if hi < 2:
        primes_in_range = []
    else:
        sieve_list = sieve(hi)
        primes_in_range = [p for p in range(lo, hi + 1) if sieve_list[p]]

    if len(primes_in_range) < 2:
        return None

    max_gap = 0
    result = None
    for i in range(len(primes_in_range) - 1):
        p = primes_in_range[i]
        q = primes_in_range[i + 1]
        gap = q - p
        if gap > max_gap:
            max_gap = gap
            result = (gap, p, q)

    return result

