    tokens = []
    for word in text.split():
        i = 0
        while i < len(word):
            tokens.append(word[i:i+width])
            i += width

    lines = []
    current_line = []
    current_length = 0
    for token in tokens:
        if not current_line:
            current_line.append(token)
            current_length = len(token)
        else:
            if current_length + 1 + len(token) <= width:
                current_line.append(token)
                current_length += 1 + len(token)
            else:
                lines.append(current_line)
                current_line = [token]
                current_length = len(token)
    if current_line:
        lines.append(current_line)

    result = []
    for i, line_tokens in enumerate(lines):
        if i == len(lines) - 1 or len(line_tokens) == 1:
            justified = ' '.join(line_tokens)
            if len(justified) < width:
                justified += ' ' * (width - len(justified))
            result.append(justified)
        else:
            total_spaces = width - sum(len(t) for t in line_tokens)
            num_gaps = len(line_tokens) - 1
            if num_gaps == 0:
                justified = line_tokens[0].ljust(width)
                result.append(justified)
                continue
            base = total_spaces // num_gaps
            extra = total_spaces % num_gaps
            spaces = []
            for j in range(num_gaps):
                spaces.append(base + (1 if j < extra else 0))
            line = line_tokens[0]
            for j in range(num_gaps):
                line += ' ' * spaces[j]
                line += line_tokens[j+1]
            result.append(line)
    return result

